suppressPackageStartupMessages({library(dplyr);library(tidyr);library(readr);library(jsonlite)})
repo <- getOption('tbl.repo_root')
out <- getOption('tbl.results_dir')
inputs <- getOption('tbl.input_dir')
cfg <- fromJSON(file.path(repo,'Parameters/valuation_settings.json'))
locs <- read_csv(file.path(repo,'Sources/country_region_mapping_45.csv'),show_col_types=FALSE)
stopifnot(nrow(locs)==45,!anyDuplicated(locs$location_id),cfg$income_elasticity_primary==1,cfg$primary_HALE_factor==.5)
read_input <- function(name) read_csv(file.path(inputs,name),show_col_types=FALSE)
raw <- read_input('gbd_burden_both_sexes.csv.gz')
pop <- read_input('population_age_specific_both_sexes.csv.gz')
dalys <- read_input('gbd_all_age_dalys.csv')
hale <- read_input('hale_all_age.csv') %>% rename(LE=HALE,LE_lower=HALE_lower,LE_upper=HALE_upper)
popall <- read_input('population_all_age.csv')
stopifnot(n_distinct(raw$rei_id)==1,unique(raw$rei_id)==86,n_distinct(raw$cause_id)==1,unique(raw$cause_id)==426)
stopifnot(nrow(dalys)==45*34*3,!anyDuplicated(dalys[c('location_id','year','sex_id')]))
for(x in list(hale,popall)) stopifnot(!anyDuplicated(x[c('location_id','year','sex_id')]))
macro <- read_csv(file.path(repo,'Sources/WDI_macro_long.csv'),show_col_types=FALSE) %>% select(Country.Code=Country_Code,year,indicator,value) %>% pivot_wider(names_from=indicator,values_from=value) %>% rename(GDPpc_const2021=NY.GDP.PCAP.PP.KD,GDP_const2021=NY.GDP.MKTP.PP.KD,WDI_population=SP.POP.TOTL)
usa_ref <- macro %>% filter(Country.Code=='USA',year==2023) %>% pull(GDPpc_const2021)
K <- cfg$rebasing_2021_to_2023
stopifnot(length(usa_ref)==1,abs(usa_ref-cfg$GDPpc_USA_2023_constant2021)<1e-7)
a <- dalys %>% left_join(hale,by=c('location_id','year','sex_id')) %>% left_join(locs %>% select(location_id,Country.Code),by='location_id') %>% left_join(macro,by=c('Country.Code','year')) %>% left_join(popall,by=c('location_id','year','sex_id')) %>% mutate(valuation_available=is.finite(GDPpc_const2021)&is.finite(GDP_const2021))
stopifnot(nrow(a)==4590,!anyNA(a$LE),!anyNA(a$population),all(a$LE>0),all(a$population>0))
coverage <- a %>% filter(sex_name=='Both') %>% group_by(year) %>% summarise(study_countries=n_distinct(location_id),valuation_countries=sum(valuation_available),missing_countries=paste(location_name[!valuation_available],collapse='; '),.groups='drop')
fullids <- a %>% filter(sex_name=='Both') %>% group_by(location_id) %>% summarise(complete=all(valuation_available),.groups='drop') %>% filter(complete) %>% pull(location_id)
stopifnot(length(fullids)==43,coverage$valuation_countries[coverage$year==2023]==45)
legacy <- a %>% filter(valuation_available) %>% mutate(GDPpc_2023=GDPpc_const2021*K,GDP=GDP_const2021*K,VSL=cfg$VSL_USA_2023*(GDPpc_const2021/usa_ref)^cfg$income_elasticity_primary,VSLY=VSL/(LE*cfg$primary_HALE_factor),VLW=DALYs*VSLY,VLW_GDP_ratio=100*VLW/GDP,VLW_per_capita=VLW/population,VLW_trillion=VLW/1e12,VLW_DALY_lower=DALYs_lower*VSLY,VLW_DALY_upper=DALYs_upper*VSLY)
stopifnot(nrow(legacy)==4548,!anyNA(legacy$VLW),all(legacy$VLW>0))
all45 <- raw %>% filter(age_id==22,metric_name=='Number') %>% transmute(location_id,location_name,region_6,year,DALYs=val,DALYs_lower=lower,DALYs_upper=upper)
epi <- bind_rows(all45 %>% group_by(region=region_6,year) %>% summarise(DALYs=sum(DALYs),.groups='drop'),all45 %>% group_by(year) %>% summarise(region='Asia',DALYs=sum(DALYs),.groups='drop'))
provided_asr <- raw %>% filter(age_name=='Age-standardized',metric_name=='Rate') %>% select(location_id,year,provided=val)
w1 <- read_csv(file.path(repo,'Sources/GBD_standard_weights_used.csv'),show_col_types=FALSE) %>% select(age_id,w)
ck <- raw %>% filter(age_id%in%w1$age_id,metric_name=='Rate') %>% left_join(w1,by='age_id') %>% group_by(location_id,year) %>% summarise(calc=sum(val*w),.groups='drop') %>% left_join(provided_asr,by=c('location_id','year'))
stopifnot(max(abs(ck$calc/ck$provided-1))<1e-10)
write_csv(locs,file.path(out,'Data/country_region_mapping.csv'))
write_csv(a,file.path(out,'Data/all_45_country_year_sex_inputs_with_missingness.csv'))
write_csv(coverage,file.path(out,'Tables/country_coverage_by_year.csv'))
write_csv(legacy,file.path(out,'Data/analysis_ready_primary_valuation.csv'))
write_csv(epi,file.path(out,'Data/epidemiological_counts_45countries.csv'))
write_csv(ck,file.path(out,'QA/age_standard_check.csv'))
write_csv(read_csv(file.path(repo,'Parameters/valuation_parameters.csv'),show_col_types=FALSE),file.path(out,'Tables/valuation_parameters.csv'))
saveRDS(list(legacy=legacy,all_inputs=a,epi=epi,all45=all45,raw=raw,pop=pop,locs=locs,fullids=fullids,w1=w1,provided_asr=provided_asr,usa_ref=usa_ref,K=K,cfg=cfg),file.path(out,'Data/prepared_inputs.rds'))
cat('Prepared',nrow(a),'input rows;',nrow(legacy),'valued rows;',length(fullids),'fixed-panel countries.\n')
